export const BODY: string = "\n<p>إخفاء وجه أو عنوان في صورة يستغرق بضع دقائق فقط. اطلِ فوق الجزء الحساس بفرشاة وراجع النتيجة ونزّل النسخة المراقبة.</p>\n<p>في هذا البرنامج التعليمي نمر بالعملية كاملة. سنرى وضعي الفرشاة والصورة الكاملة والتعتيم والتبكسيل وحجم الفرشاة والمراجعات التي تؤكد أن لا شيء ما زال مقروءًا.</p>\n<p>في النهاية ستستطيع مراقبة وجه أو لوحة أو لقطة شاشة أو مستند دون مشاكل على أي جهاز. وأبقِ الأصل دون مراقبة منفصلًا حتى تراجع التنزيل.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: اعد قائمة ما يحتاج إخفاء</h2>\n<p>افتح الصورة الأصلية واعد قائمة بكل ما هو حساس فيها: وجوه وعناوين ولوحات وشاشات ومستندات وأسماء على بطاقات. وراجع الخلفية إضافة إلى المقدمة.</p>\n<p>ابحث عن الانعكاسات أيضًا: وجه قد يظهر في مرآة أو نافذة أو نظارة شمسية، وكل نسخة تحتاج مراقبة، لا الرئيسية فقط. وقرر إن كنت ستعتّم أم تبكسل قبل أن تبدأ: التبكسيل أكثر أمانًا للنص والأرقام، بينما تعتيم قوي يعمل جيدًا للوجوه والخلفيات.</p>\n<p>افتح <a href=\"/ar/tammih-wa-tabaksul-as-sura/\">أداة تعتيم وتبكسيل الصورة</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">كيف تعتّم أو تبكسل صورة في ست خطوات</h2>\n<p>العملية نفسها لوجه أو لوحة أو لقطة شاشة. ارفع واختر الوضع واطلِ أو طبّق وراجع ونزّل.</p>\n<p>خذ وقتك مع خطوة الطلاء: ضربة فرشاة دقيقة الآن توفر عليك اكتشاف تفصيل مقروء بعد مشاركة الصورة بالفعل. وافتح الملف المنزّل مرة قبل مشاركته، وراجعه بالحجم الكامل وتأكد من أن كل تفصيل حساس مخفي.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصق لقطة شاشة بـCtrl+V.</li>\n<li>اختر وضع منطقة الفرشاة للطلاء فوق تفاصيل محددة، أو وضع الصورة الكاملة لتعتيم الصورة كلها.</li>\n<li>اختر تعتيم ناعم أو فسيفساء مبكسلة، ثم اضبط حجم الفرشاة والشدة أو حجم الكتلة.</li>\n<li>اطلِ فوق كل منطقة حساسة بالفرشاة، مغطيًا الوجوه بالكامل والنص بسخاء.</li>\n<li>قرّب وراجع النتيجة لتأكيد أن لا شيء ما زال مقروءًا أو مميزًا.</li>\n<li>اختر صيغة التصدير والجودة، ثم انقر تنزيل لحفظ الصورة المراقبة.</li>\n</ol>\n<h2 id=\"choosing-blur-or-pixelate\">كيف تختار بين التعتيم والتبكسيل</h2>\n<p>اختر تعتيم ناعم للوجوه والخلفيات: تعتيم قوي يزيل الملامح مع إبقاء الصورة بمظهر طبيعي، ويناسب الصور الشخصية.</p>\n<p>اختر فسيفساء مبكسلة للنص والأرقام والعناوين: كتل الفسيفساء تدمر أشكال الحروف تمامًا، بينما تعتيم ناعم قد يترك حدودها مقروءة. ويمكنك مزج الاثنين في نفس الصورة: اطلِ وجهًا بتعتيم ولوحة بتبكسيل، مستخدمًا مبدل الوضع بين الضربات.</p>\n<p>وعند الشك، استخدم التبكسيل: فسيفساء أقوى قليلًا مما يلزم تبدو مقصودة، بينما تعتيم أضعف قليلًا مما يلزم يترك التفصيل مقروءًا.</p>\n<h2 id=\"using-brush-mode\">كيف تستخدم وضع منطقة الفرشاة</h2>\n<p>وضع منطقة الفرشاة هو الخيار الدقيق: يطلي التأثير بالضبط حيث تحتاجه، وبقية الصورة تبقى حادة وسليمة.</p>\n<p>ابدأ بفرشاة كبيرة للمنطقة الرئيسية، مثل وجه كامل: غطِّ الرأس بالكامل، بما فيه خط الشعر والأذنين والذقن، لا العينين فقط. وبدّل إلى فرشاة أصغر للحواف: فرشاة صغيرة تتيح تتبع كلمة واحدة أو تنظيف حافة منطقة مراقبة دون لمس البقية.</p>\n<p>زر التراجع يزيل ضربتك الأخيرة، وزر إعادة الضبط يمسح كل ضربات الفرشاة. استخدمهما بحرية: إعادة ضربة أسرع من مشاركة صورة مراقبة بشكل سيئ.</p>\n<h2 id=\"using-whole-image-mode\">كيف تستخدم وضع الصورة الكاملة</h2>\n<p>وضع الصورة الكاملة يطبق التأثير على الصورة كلها دفعة واحدة. إنه الخيار الصحيح عندما تكون الصورة كلها حساسة، أو عندما تريد خلفية معتّمة لتصميم.</p>\n<p>بدّل المنطقة المستهدفة إلى صورة كاملة وتطبق الأداة شدة التعتيم أو التبكسيل الحالية على الإطار الكامل: تبقى الألوان والمزاج، لكن لا تفصيل ينجو. وصورة معتّمة تمامًا خلفية جيدة لنص أو شريحة عرض: تضيف الصورة لونًا دون تشتيت عن الكلمات فوقها.</p>\n<p>لا تستخدم وضع الصورة الكاملة لصورة تريد أن يراها الناس بوضوح: صورة معتّمة تمامًا تخفي الموضوع إضافة إلى التفاصيل الحساسة، فنادرًا ما تكون الخيار الصحيح.</p>\n<h2 id=\"setting-brush-size\">كيف تضبط حجم الفرشاة</h2>\n<p>يجب أن يطابق حجم الفرشاة التفصيل الذي تخفيه: وجه يحتاج فرشاة كبيرة، ولوحة تحتاج فرشاة متوسطة، وكلمة واحدة تحتاج فرشاة صغيرة.</p>\n<p>فرشاة كبيرة جدًا تراقب أكثر مما أردت: قد تغطي وجهًا مجاورًا أو جزءًا مفيدًا من الصورة لم يكن يحتاج إخفاء. وفرشاة صغيرة جدًا تأخذ ضربات كثيرة لتغطية منطقة كبيرة، والفجوات بين الضربات قد تترك أجزاء صغيرة من التفصيل الحساس مرئية.</p>\n<p>اضبط الحجم وأنت تعمل: ابدأ كبيرًا للمنطقة الرئيسية، ثم بدّل إلى صغير لتنظيف الحواف وتغطية أي نقطة فاتتك.</p>\n<h2 id=\"setting-strength\">كيف تضبط شدة التعتيم وحجم الكتلة</h2>\n<p>شدة التعتيم وحجم كتلة الفسيفساء يتحكمان في كم معلومات ينجو: القيم الأعلى تخفي أكثر، والأدنى تخفي أقل.</p>\n<p>للوجوه، استخدم تعتيمًا قويًا أو كتلًا كبيرة: تعتيم خفيف يترك العينين والابتسامة مرئيتين لا يحمي أحدًا، والكتل الصغيرة ما زالت تُظهر شكل الوجه. وللقطات شاشة صغيرة، حجم كتلة معتدل يكفي: النص صغير، فحتى فسيفساء متواضعة تدمر أشكال الحروف تمامًا.</p>\n<p>اختبر النتيجة بتقريب الصورة: إذا ما زلت تستطيع قراءة النص أو تمييز الوجه بالحجم الكامل، زد الشدة وراجع مجددًا.</p>\n<h2 id=\"fixing-mistakes\">كيف تصحح أخطاء أثناء الطلاء</h2>\n<p>إذا خرجت ضربة خطأ، استخدم زر التراجع لإزالتها: التراجع يعمل ضربة بضربة، فتستطيع الرجوع حركة واحدة في كل مرة دون فقدان العمل الجيد.</p>\n<p>وإذا بدت المراقبة كلها سيئة، استخدم زر إعادة الضبط لمسح كل ضربات الفرشاة: البدء من جديد أسرع من محاولة إصلاح مجموعة ضربات فوضوية. وانتبه للفجوات بين الضربات: شريط رفيع مرئي من نص بين ضربتي فرشاة قد يكشف الكلمة المخفية، فتداخل ضرباتك قليلًا.</p>\n<p>وراجع حواف كل منطقة مراقبة: وجه بأذن مرئية أو لوحة برقم مرئي ليست مخفية جيدًا، حتى لو كان الوسط مغطى.</p>\n<h2 id=\"preview-and-compare\">كيف تراجع المعاينة قبل التنزيل</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل: قرّب على كل منطقة مراقبة بالحجم الكامل وتأكد من أن لا ملامح أو حرف أو رقم ما زال مقروءًا.</p>\n<p>راجع الخلفية إضافة إلى المقدمة: انعكاس في نافذة أو مرآة قد يُظهر الوجه أو العنوان نفسه الذي راقبته للتو في الصورة الرئيسية. وانظر إلى الصورة على شاشة أكبر إن استطعت: تفصيل يبدو مخفيًا على هاتف قد يكون مقروءًا على شاشة حاسوب، حيث تُعرض الصورة أكبر.</p>\n<p>إذا بقي شيء مقروءًا، زد الشدة أو أضف ضربة أخرى: تصحيحه الآن أسهل بكثير من سحب صورة شاركتها بالفعل.</p>\n<h2 id=\"choosing-export-format\">كيف تختار صيغة التصدير</h2>\n<p>اختر JPG للصور التي تنوي مشاركتها. يبقي الملفات صغيرة ويعمل في كل مكان، والمناطق المراقبة تُضغط جيدًا.</p>\n<p>اختر PNG للقطات الشاشة والرسوم ذات النص: لا يفقد PNG شيئًا، فتبقى الحواف الحادة للأجزاء غير المراقبة واضحة، ويحافظ على الشفافية. واختر WebP عندما تريد ملفات صغيرة بجودة جيدة: يعمل جيدًا لصور الويب، مع أن بعض الأنظمة القديمة ما زالت ترفض الصيغة.</p>\n<p>تذكر أن منزلق الجودة يُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره. هذا سلوك طبيعي، لا مشكلة في الأداة.</p>\n<h2 id=\"blurring-on-mobile\">كيف تعتّم على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة باللمس، فتستطيع مراقبة صورة على الهاتف نفسه الذي التقطها. ارفعها من معرضك واطلِ فوق المناطق الحساسة بإصبعك.</p>\n<p>استخدم فرشاة أكبر على شاشة صغيرة: الطلاء بالإصبع أقل دقة من الفأرة، ففرشاة أكبر تغطي المنطقة بموثوقية دون الحاجة إلى ضربات كثيرة. وقرّب قبل طلاء تفاصيل صغيرة: لوحة أو كلمة واحدة تحتاج نظرة قريبة، والتقريب يجعل الضربات دقيقة حتى على الهاتف.</p>\n<p>تُحفظ الملفات المنزّلة في مجلد التنزيلات المعتاد لديك. ومن هناك يمكنك مشاركة الصورة المراقبة مباشرة إلى تطبيق محادثة أو بريد أو منشور اجتماعي.</p>\n<h2 id=\"blurring-screenshots\">كيف تعتّم لقطة شاشة</h2>\n<p>الصق لقطة شاشة مباشرة بـCtrl+V لتتخطى خطوة الحفظ. تظهر الصورة في الأداة فورًا، جاهزة للمراقبة.</p>\n<p>اطلِ فوق الأسماء وعناوين البريد وكلمات المرور والروابط الداخلية: لقطة لوحة غالبًا تكشف أكثر من الجزء الذي أردت مشاركته. واستخدم التبكسيل للنص في لقطات الشاشة: الفسيفساء تدمر أشكال الحروف تمامًا، بينما تعتيم ناعم قد يترك الكلمات مقروءة جزئيًا بالحجم الكامل.</p>\n<p>صدّر لقطات الشاشة كـPNG: الصيغة دون فقدان تبقي النص غير المراقب حادًا، وهو أمر مهم عندما يجب أن تُظهر اللقطة ضبطًا أو رسالة خطأ.</p>\n<h2 id=\"blurring-documents\">كيف تعتّم صورة مستند</h2>\n<p>صور المستندات غالبًا تحتوي أسماء وعناوين وأرقام هوية في أماكن عدة. اعد قائمتها كلها قبل أن تبدأ الطلاء، فلا يفوتك أي منها.</p>\n<p>غطِّ سطر النص كله، لا الكلمة الحساسة فقط: طول السطر والكلمات المحيطة قد تكشف الجزء المخفي. وراجع حواف صورة المستند: صفحة ثانية أو انعكاس أو ظل قد يحمل نفس المعلومات في مكان لم تتوقعه.</p>\n<p>ولمستندات يجب مشاركتها، فكر في قص الأجزاء الحساسة تمامًا: القص يزيل البيانات إلى الأبد، بينما التعتيم يخفيها فقط في ذلك الملف.</p>\n<h2 id=\"troubleshooting\">حل المشاكل الشائعة في المراقبة</h2>\n<p>إذا بقي وجه مميزًا، فالتعتيم خفيف جدًا أو الكتل صغيرة جدًا: زد الشدة واطلِ فوق الوجه مجددًا حتى لا تكون أي ملامح مرئية.</p>\n<p>وإذا بقي النص مقروءًا، بدّل من التعتيم إلى التبكسيل: فسيفساء بكتل كبيرة تدمر أشكال الحروف بموثوقية أكبر بكثير من تعتيم ناعم. وإذا فقد زر التراجع، راجع إن كنت في وضع الصورة الكاملة: زرا التراجع وإعادة الضبط يظهران فقط في وضع منطقة الفرشاة، حيث توجد ضربات للتراجع عنها.</p>\n<p>وإذا بدت المعاينة مختلفة عن التنزيل، راجع صيغة التصدير والجودة: ضبط جودة JPG منخفض قد ينعّم الصورة كلها، بما فيها الأجزاء التي أردتها حادة.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لمراقبة أكثر أمانًا</h2>\n<p>راقب بسخاء: تغطية قليل إضافي لا تضر، بينما ترك شريط مرئي من وجه أو رقم يُحبط الغرض كله.</p>\n<p>قرّب بعد كل ضربة: مراجعة سريعة بالتقريب تكتشف الفجوات والنقاط الفائتة قبل أن تصبح خطأ مشاركًا. وشارك الملف المراقب فقط: احفظ الأصل في مجلد منفصل، ولا ترفقه أبدًا مع نفس الرسالة أو المنشور كالنسخة المراقبة.</p>\n<p>راجع البيانات الوصفية بعد التصدير: الأداة تزيل وسوم GPS، لكن تأكد من أن الملف المنزّل لا يحمل أي سجل موقع قبل مشاركته علنًا.</p>\n<h2 id=\"blurring-for-presentations\">كيف تعتّم صورة لعرض تقديمي</h2>\n<p>صورة معتّمة خلفية نظيفة للشرائح: الألوان الناعمة تضيف اهتمامًا بصريًا، بينما النص فوقها يبقى حادًا وسهل القراءة من آخر القاعة.</p>\n<p>استخدم وضع الصورة الكاملة بتعتيم معتدل، ثم ضع عنوانك ونقاطك فوقه: يجب أن يكون التعتيم قويًا بما يكفي ليكون النص مقروءًا، لكن خفيفًا بما يكفي ليبقى اللون حيًا. وأبقِ نص الشريحة كبيرًا وبتباين عالٍ: نص أبيض فوق صورة معتّمة داكنة يعمل جيدًا، بينما نص داكن يحتاج خلفية معتّمة فاتحة ليُقرأ.</p>\n<p>صدّر الخلفية كـJPG بضبط جودة عالية: خلفية نظيفة تبقي الشريحة كلها بمظهر احترافي، بينما تصدير منخفض الجودة ينعّم النص أيضًا.</p>\n<p>للمقارنة، اقرأ <a href=\"/ar/blog/tammih-vs-tabaksul-as-sura/\">تعتيم أم تبكسيل: كيف تخفي الوجوه والنص والتفاصيل</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-tammih-wa-tabaksul-as-suwar/\">دليل تعتيم وتبكسيل الصور الكامل</a>، ولإزالة بيانات الموقع من الصورة استخدم <a href=\"/ar/izala-bayanat-as-sura/\">أداة إزالة بيانات الصورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أعتّم وجهًا واحدًا فقط في صورة جماعية؟","answer":"استخدم وضع منطقة الفرشاة واطلِ فوق ذلك الوجه فقط بفرشاة كبيرة وتعتيم قوي أو فسيفساء. وبقية الصورة تبقى حادة. وقرّب بعدها لتأكيد أن الرأس كله مغطى، بما فيه الأذنان والذقن."},{"question":"هل يمكنني تعتيم أجزاء وتبكسيل أجزاء أخرى من نفس الصورة؟","answer":"نعم، اطلِ الوجه بتعتيم ناعم، ثم بدّل إلى فسيفساء مبكسلة واطلِ فوق النص أو اللوحة. ويمكنك مزج التأثيرين في صورة واحدة بتغيير الوضع بين الضربات."},{"question":"أي حجم فرشاة يجب أن أستخدم للوحة؟","answer":"فرشاة متوسطة تغطي اللوحة في ضربتين أو ثلاث تعمل جيدًا. واستخدم التبكسيل بحجم كتلة معتدل إلى كبير، إذ يحتاج النص الفسيفساء لتدمير أشكال الحروف. وقرّب لتأكيد أن كل رقم مخفي."},{"question":"كيف أعتّم لقطة شاشة على هاتفي؟","answer":"افتح الأداة في متصفح هاتفك وارفع اللقطة من معرضك واختر وضع منطقة الفرشاة. واطلِ فوق الأسماء وكلمات المرور بإصبعك، مستخدمًا فرشاة كبيرة وتبكسيلًا للنص، ثم نزّل النتيجة."},{"question":"لماذا يفقد زرا التراجع وإعادة الضبط؟","answer":"يظهران فقط في وضع منطقة الفرشاة، حيث توجد ضربات للتراجع عنها. وفي وضع الصورة الكاملة لا توجد ضربات فرشاة، فتُخفى الأزرار. وعد إلى وضع منطقة الفرشاة للطلاء واستخدام التراجع."},{"question":"هل مشاركة صورة معتّمة لطفلي عبر الإنترنت آمنة؟","answer":"وجه معتّم بقوة أو مبكسل أكثر أمانًا بكثير من وجه مرئي، لكن لا طريقة مثالية. واستخدم فسيفساء كبيرة أو تعتيمًا قويًا، وغطِّ الرأس كله، وراجع النتيجة بالحجم الكامل قبل المشاركة."}];
